cd /data; sqlite3 -header current.db "select c.change_id, k.kind_code, p.pool_code, c.effective_at_ms, c.before_json, c.after_json from change_events c join change_kinds k using(kind_id) left join worker_pools p using(pool_id) where c.effective_at_ms>=1778148000000 and c.effective_at_ms<1778155200000;
select p.pool_code, s.signal_code, s.unit, case when measured_at_ms>=1778148000000 and measured_at_ms<1778151600000 then 'reference_10_11' when measured_at_ms>=1778151600000 and measured_at_ms<1778155200000 then 'incident_11_12' end period, round(avg(value),4) mean_value, count(*) n, min(measured_at_ms), max(measured_at_ms) from telemetry_samples t join worker_pools p using(pool_id) join telemetry_signals s using(signal_id) where p.pool_code like 'sync%' and measured_at_ms>=1778148000000 and measured_at_ms<1778155200000 group by 1,2,4 order by 1,2,4;
select o.opened_at_ms>=1778151600000 inc, p.pool_code, round(avg(a.queue_ms),2) q, round(avg(a.execution_ms),2) e, count(*) from attempt_events a join logical_operations o using(operation_id) join route_assignments ra on ra.route_id=o.route_id and o.opened_at_ms>=ra.effective_from_ms and o.opened_at_ms<ra.effective_to_ms join worker_pools p on p.pool_id=ra.pool_id join service_routes r on r.route_id=o.route_id where r.service_id=2 and o.opened_at_ms>=1778148000000 and o.opened_at_ms<1778155200000 group by 1,2;"

